INSERT INTO recipes (id, title, slug, description, cuisine, dietary_type, prep_time_minutes, cook_time_minutes, servings, difficulty, instructions, is_system_recipe) VALUES
  ('471211e4-c284-5f61-9057-f5cbd725c7ce', 'Palak Paneer', 'palak-paneer', 'Soft paneer cubes in a smooth, mildly spiced spinach gravy.', 'North Indian', 'vegetarian', 15, 20, 2, 'easy', '["Blanch the spinach in boiling water for 2 minutes, plunge into cold water and blend to a smooth puree with the green chillies.", "Heat oil, add cumin seeds, then saute chopped onion, ginger and garlic until golden.", "Add chopped tomato and cook until soft, then stir in the spinach puree and salt; simmer for 5 minutes.", "Add paneer cubes and garam masala and simmer for 3 minutes.", "Finish with cream if using and serve hot with roti or rice."]'::jsonb, true);
