INSERT INTO recipes (id, title, slug, description, cuisine, dietary_type, prep_time_minutes, cook_time_minutes, servings, difficulty, instructions, is_system_recipe) VALUES
  ('cdea69c7-6446-5eab-97a4-545775905320', 'Aloo Gobi', 'aloo-gobi', 'Dry-style potato and cauliflower sabzi with turmeric and cumin.', 'North Indian', 'vegan', 10, 25, 2, 'easy', '["Cut potatoes into cubes and cauliflower into medium florets.", "Heat oil, add cumin seeds, then saute onion, ginger and green chilli for 2 minutes.", "Add potatoes, turmeric and salt; cover and cook for 7 minutes.", "Add cauliflower, chopped tomato, chilli powder and coriander powder; cover and cook on low heat for 12 minutes, stirring gently.", "Sprinkle garam masala and coriander leaves before serving."]'::jsonb, true);
