INSERT INTO recipes (id, title, slug, description, cuisine, dietary_type, prep_time_minutes, cook_time_minutes, servings, difficulty, instructions, is_system_recipe) VALUES
  ('0122c8eb-8865-5238-8771-881e771b0f31', 'Dal Tadka', 'dal-tadka', 'Everyday toor dal finished with a sizzling ghee tempering.', 'North Indian', 'vegetarian', 10, 30, 3, 'easy', '["Rinse the dal and pressure cook with 2.5 cups water, turmeric and salt for 3-4 whistles.", "Mash the cooked dal lightly and keep it simmering.", "Heat ghee, add cumin, asafoetida, chopped garlic and green chilli; fry until the garlic is golden.", "Add onion and tomato and cook until soft, then add chilli powder.", "Pour the tempering over the dal, simmer for 2 minutes and garnish with coriander."]'::jsonb, true);
