INSERT INTO recipes (id, title, slug, description, cuisine, dietary_type, prep_time_minutes, cook_time_minutes, servings, difficulty, instructions, is_system_recipe) VALUES
  ('c0ee3314-b89d-5add-8ae3-b4a920dad6f2', 'Masoor Dal', 'masoor-dal', 'Quick-cooking red lentils with tomato and cumin.', 'North Indian', 'vegan', 5, 20, 3, 'easy', '["Rinse the dal and boil with 3 cups water, turmeric and salt until soft, about 15 minutes.", "Heat oil, add cumin and garlic, then onion; fry until golden.", "Add tomato and chilli powder and cook until mushy.", "Stir the tempering into the dal and simmer for 3 minutes. Garnish and serve."]'::jsonb, true);
