INSERT INTO recipes (id, title, slug, description, cuisine, dietary_type, prep_time_minutes, cook_time_minutes, servings, difficulty, instructions, is_system_recipe) VALUES
  ('d8866305-ef93-5717-a3c8-2ed21390d681', 'Jeera Rice', 'jeera-rice', 'Fragrant basmati rice tempered with cumin and ghee.', 'North Indian', 'vegetarian', 5, 20, 2, 'easy', '["Rinse the rice and soak for 15 minutes; drain.", "Heat ghee, add cumin seeds and bay leaf until they crackle.", "Add rice and saute gently for 1 minute, then add 1.75 cups hot water and salt.", "Cover and cook on low heat for 12-15 minutes until the water is absorbed. Rest 5 minutes and fluff."]'::jsonb, true);
