INSERT INTO recipes (id, title, slug, description, cuisine, dietary_type, prep_time_minutes, cook_time_minutes, servings, difficulty, instructions, is_system_recipe) VALUES
  ('1e2d3995-bd92-5fcc-9f2c-712a6ef2acba', 'Rajma Chawal', 'rajma-chawal', 'Punjabi kidney beans in an onion-tomato gravy, served with rice.', 'North Indian', 'vegan', 480, 45, 3, 'medium', '["Soak rajma overnight, then pressure cook with salt for 6-7 whistles until very soft.", "Heat oil, add cumin, then onion and fry until deep golden; add ginger garlic paste.", "Add pureed tomato and the powdered spices; cook until oil separates.", "Add rajma with its cooking water, mash a few beans and simmer for 15 minutes.", "Cook the rice separately and serve with the rajma, topped with garam masala and coriander."]'::jsonb, true);
