  ('ac00cbde-97b4-5135-9ad6-d05551e54c28', 'Chole', 'chole', 'Spicy chickpea curry, perfect with bhature, puri or rice.', 'North Indian', 'vegan', 480, 40, 3, 'medium', '["Soak chickpeas overnight and pressure cook with salt for 5-6 whistles.", "Heat oil, add cumin, then fry onion until brown; add ginger garlic paste and green chilli.", "Add tomato puree, turmeric, chilli powder and chole masala; cook until thick.", "Add chickpeas with some cooking water, simmer for 15 minutes, mashing a few chickpeas to thicken.", "Garnish with coriander and serve."]'::jsonb, true);
