INSERT INTO recipes (id, title, slug, description, cuisine, dietary_type, prep_time_minutes, cook_time_minutes, servings, difficulty, instructions, is_system_recipe) VALUES
  ('c06287e2-3f77-54a6-8045-4ddaf5a2d53e', 'Paneer Bhurji', 'paneer-bhurji', 'Scrambled paneer with onion, tomato and spices - ready in 20 minutes.', 'North Indian', 'vegetarian', 10, 10, 2, 'easy', '["Crumble the paneer with your fingers.", "Heat oil, add cumin, then onion and green chilli; saute until translucent.", "Add tomato, capsicum, turmeric, chilli powder and salt; cook until soft.", "Add paneer and garam masala, toss for 2-3 minutes and finish with coriander."]'::jsonb, true);
