INSERT INTO recipes (id, title, slug, description, cuisine, dietary_type, prep_time_minutes, cook_time_minutes, servings, difficulty, instructions, is_system_recipe) VALUES
  ('21ca246b-dea7-58dd-9165-fd8119c1149d', 'Matar Paneer', 'matar-paneer', 'Paneer and green peas in a homestyle tomato gravy.', 'North Indian', 'vegetarian', 10, 25, 3, 'easy', '["Blend onion and tomato into a puree.", "Heat oil, add cumin and ginger garlic paste, then the puree; cook until oil separates.", "Add the powdered spices and salt, then peas and 1 cup water; simmer for 8 minutes.", "Add paneer cubes and garam masala; simmer for 3 minutes and garnish."]'::jsonb, true);
