INSERT INTO recipes (id, title, slug, description, cuisine, dietary_type, prep_time_minutes, cook_time_minutes, servings, difficulty, instructions, is_system_recipe) VALUES
  ('111dd8a3-b44b-5aef-a487-c5be813b1d1b', 'Aloo Matar', 'aloo-matar', 'Comforting potato and peas curry.', 'North Indian', 'vegan', 10, 25, 3, 'easy', '["Peel and cube the potatoes.", "Heat oil, add cumin and grated ginger, then onion; saute for 2 minutes.", "Add chopped tomato and spices and cook until soft.", "Add potatoes, peas and 1.5 cups water; pressure cook for 2 whistles or simmer covered for 15 minutes.", "Finish with garam masala and coriander."]'::jsonb, true);
