INSERT INTO recipes (id, title, slug, description, cuisine, dietary_type, prep_time_minutes, cook_time_minutes, servings, difficulty, instructions, is_system_recipe) VALUES
  ('2fd266c4-8a4d-5564-b9b2-877bb1a76404', 'Bhindi Masala', 'bhindi-masala', 'Crisp-tender okra tossed with onions and spices.', 'North Indian', 'vegan', 10, 20, 2, 'easy', '["Wash and dry the okra completely, then cut into 1-inch pieces.", "Heat oil and fry the okra on medium heat, uncovered, until no longer sticky; set aside.", "In the same pan add cumin and sliced onion; fry until golden, then add tomato and spices.", "Return the okra, add amchur and salt, and toss for 3 minutes."]'::jsonb, true);
