INSERT INTO recipes (id, title, slug, description, cuisine, dietary_type, prep_time_minutes, cook_time_minutes, servings, difficulty, instructions, is_system_recipe) VALUES
  ('8ca7f0ce-9387-5974-87e4-a12b5e41dcf5', 'Baingan Bharta', 'baingan-bharta', 'Smoky roasted brinjal mash with onion, tomato and green chilli.', 'North Indian', 'vegan', 10, 30, 2, 'medium', '["Roast the brinjal directly over a flame until the skin is charred and the flesh is soft.", "Cool, peel and mash the flesh.", "Heat oil, add cumin, garlic and green chilli, then onion; fry until golden.", "Add tomato and chilli powder and cook until soft; add the mashed brinjal and salt.", "Cook for 5 minutes and garnish with coriander."]'::jsonb, true);
