INSERT INTO recipes (id, title, slug, description, cuisine, dietary_type, prep_time_minutes, cook_time_minutes, servings, difficulty, instructions, is_system_recipe) VALUES
  ('59f5bac7-dca5-5722-b8e5-e02ee226cf9f', 'Kadai Paneer', 'kadai-paneer', 'Paneer and capsicum in a spicy, coarsely ground masala.', 'North Indian', 'vegetarian', 15, 20, 2, 'medium', '["Cut paneer, capsicum and one onion into cubes; puree the tomato.", "Heat oil, saute the cubed onion and capsicum for 2 minutes and set aside.", "In the same pan cook ginger garlic paste and tomato puree with the spices until thick.", "Add paneer, the sauteed vegetables and kasuri methi; toss for 3 minutes."]'::jsonb, true);
