INSERT INTO recipes (id, title, slug, description, cuisine, dietary_type, prep_time_minutes, cook_time_minutes, servings, difficulty, instructions, is_system_recipe) VALUES
  ('879dcc28-2be3-55a9-bb01-037986bd5bee', 'Paneer Butter Masala', 'paneer-butter-masala', 'Rich, mildly sweet tomato-butter gravy with paneer.', 'North Indian', 'vegetarian', 15, 25, 3, 'medium', '["Simmer tomatoes and cashews in a little water for 10 minutes, then blend smooth.", "Melt butter, add ginger garlic paste and cook for 1 minute.", "Add the tomato-cashew puree, chilli powder, salt and sugar; simmer for 8 minutes.", "Add paneer cubes, cream, garam masala and crushed kasuri methi; simmer 3 minutes."]'::jsonb, true);
