INSERT INTO recipes (id, title, slug, description, cuisine, dietary_type, prep_time_minutes, cook_time_minutes, servings, difficulty, instructions, is_system_recipe) VALUES
  ('f2c89bef-1087-55b4-9dfb-1941479b4c8a', 'Moong Dal Khichdi', 'moong-dal-khichdi', 'One-pot rice and moong dal comfort meal.', 'North Indian', 'vegetarian', 5, 25, 2, 'easy', '["Rinse rice and dal together.", "Heat ghee in a pressure cooker, add cumin, asafoetida and ginger.", "Add tomato and peas if using, then rice, dal, turmeric, salt and 4 cups water.", "Pressure cook for 3 whistles and let the pressure release naturally. Serve with curd or pickle."]'::jsonb, true);
