  ('e3008ffb-c814-599a-b055-dd968917ef0a', 'Veg Pulao', 'veg-pulao', 'Mildly spiced basmati rice with mixed vegetables.', 'North Indian', 'vegetarian', 15, 25, 3, 'easy', '["Soak the rice for 20 minutes and drain.", "Heat ghee, add cumin and bay leaf, then sliced onion; fry until light golden.", "Add ginger garlic paste and the vegetables; saute for 3 minutes.", "Add rice, garam masala, salt and 2 cups water; cover and cook on low for 15 minutes.", "Rest for 5 minutes before fluffing."]'::jsonb, true);
