INSERT INTO recipes (id, title, slug, description, cuisine, dietary_type, prep_time_minutes, cook_time_minutes, servings, difficulty, instructions, is_system_recipe) VALUES
  ('4ee76aea-c6d5-55b9-a3da-dc1bc02521d8', 'Kadhi Pakora', 'kadhi-pakora', 'Tangy curd and gram flour curry with soft onion fritters.', 'North Indian', 'vegetarian', 15, 35, 3, 'medium', '["Whisk curd, 3 tbsp gram flour, turmeric, salt and 3 cups water until smooth.", "Mix the remaining gram flour with sliced onion, chilli and salt into a thick batter; fry small pakoras and drain.", "Bring the curd mixture to a boil while stirring, then simmer for 20 minutes.", "Temper oil with cumin, mustard, fenugreek seeds, asafoetida and chilli powder; pour into the kadhi.", "Add the pakoras just before serving."]'::jsonb, true);
