INSERT INTO recipes (id, title, slug, description, cuisine, dietary_type, prep_time_minutes, cook_time_minutes, servings, difficulty, instructions, is_system_recipe) VALUES
  ('5fcb05d8-015e-544d-aeca-9b751fde0c7b', 'Lauki Chana Dal', 'lauki-chana-dal', 'Bottle gourd cooked with chana dal - light and wholesome.', 'North Indian', 'vegan', 10, 25, 3, 'easy', '["Soak chana dal for 30 minutes. Peel and cube the bottle gourd.", "Heat oil in a pressure cooker, add cumin, asafoetida and ginger, then tomato.", "Add dal, lauki, turmeric, chilli powder, salt and 2 cups water.", "Pressure cook for 3 whistles. Mash lightly and serve with roti or rice."]'::jsonb, true);
