  ('377b25fb-55f5-5943-abe6-942ac8c43369', 'Cabbage Matar Sabzi', 'cabbage-matar-sabzi', 'Stir-fried cabbage with peas.', 'North Indian', 'vegan', 10, 15, 2, 'easy', '["Finely shred the cabbage.", "Heat oil, add cumin and green chilli.", "Add cabbage, peas, turmeric and salt; cook uncovered on medium heat for 10-12 minutes, stirring often."]'::jsonb, true);
