INSERT INTO recipes (id, title, slug, description, cuisine, dietary_type, prep_time_minutes, cook_time_minutes, servings, difficulty, instructions, is_system_recipe) VALUES
  ('f2cbaa5f-93c1-5cdb-8ceb-4fb958e33918', 'Mushroom Matar', 'mushroom-matar', 'Mushrooms and peas in a spiced onion-tomato masala.', 'North Indian', 'vegan', 10, 20, 2, 'easy', '["Slice the mushrooms; chop onion and tomato.", "Heat oil, add cumin and onion and fry until golden, then ginger garlic paste.", "Add tomato and spices and cook until soft.", "Add mushrooms and peas, cook uncovered for 8-10 minutes, then add garam masala."]'::jsonb, true);
