INSERT INTO recipes (id, title, slug, description, cuisine, dietary_type, prep_time_minutes, cook_time_minutes, servings, difficulty, instructions, is_system_recipe) VALUES
  ('bd5c5e75-25d7-5f37-9c94-8a6575d6593f', 'Sarson Ka Saag', 'sarson-ka-saag', 'Slow-cooked mustard greens and spinach, finished with ghee.', 'Punjabi', 'vegetarian', 20, 40, 3, 'medium', '["Wash and chop the greens; boil with ginger, green chilli and salt for 25 minutes.", "Blend coarsely, adding the gram flour mixed with a little water to bind.", "Heat ghee, fry garlic and onion until golden and add the saag.", "Simmer for 10 minutes, stirring. Serve with makki roti or regular roti and a dollop of butter."]'::jsonb, true);
