  ('5f38a6be-e705-57b4-9d97-d228124a2679', 'Aloo Paratha', 'aloo-paratha', 'Whole wheat flatbread stuffed with spiced potato.', 'North Indian', 'vegetarian', 20, 20, 2, 'medium', '["Knead the flour with water and a pinch of salt into a soft dough; rest 15 minutes.", "Boil, peel and mash the potatoes with onion, green chilli, chilli powder, amchur, salt and coriander.", "Roll a dough ball, place filling in the centre, seal and roll gently into a paratha.", "Cook on a hot tawa, brushing both sides with ghee, until golden spots appear."]'::jsonb, true);
