  ('482ead91-1f10-50ff-9043-2d3a6635e34b', 'Paneer Paratha', 'paneer-paratha', 'Paratha stuffed with spiced grated paneer.', 'North Indian', 'vegetarian', 20, 20, 2, 'medium', '["Knead a soft dough and rest for 15 minutes.", "Grate paneer and mix with onion, green chilli, chilli powder, salt and coriander.", "Stuff, seal and roll each paratha.", "Cook on a hot tawa with ghee until golden on both sides."]'::jsonb, true);
