  ('15ab6e7c-1d14-5aea-aae6-6efe9fb29ee4', 'Methi Thepla', 'methi-thepla', 'Soft spiced flatbreads with fresh fenugreek - great for travel and tiffin.', 'Gujarati', 'vegetarian', 15, 20, 3, 'easy', '["Finely chop the methi leaves.", "Mix flour, methi, curd, spices, salt, sesame seeds and 1 tbsp oil; knead to a soft dough with water.", "Roll into thin rounds.", "Cook on a hot tawa with a little oil until both sides have light brown spots."]'::jsonb, true);
