  ('fe538bf5-ca17-504b-9fc4-e0fee19b6616', 'Missi Roti', 'missi-roti', 'Protein-rich gram flour and wheat flatbread.', 'Rajasthani', 'vegetarian', 10, 15, 2, 'easy', '["Combine both flours with onion, green chilli, spices, carom seeds and salt.", "Knead to a firm dough with water and rest for 10 minutes.", "Roll into rotis and cook on a hot tawa, brushing with ghee."]'::jsonb, true);
