INSERT INTO recipes (id, title, slug, description, cuisine, dietary_type, prep_time_minutes, cook_time_minutes, servings, difficulty, instructions, is_system_recipe) VALUES
  ('3a88f621-ba92-5a47-8afd-aba4c00f04af', 'Kanda Poha', 'kanda-poha', 'Flattened rice with onions, peanuts and a squeeze of lemon.', 'Maharashtrian', 'vegan', 10, 10, 2, 'easy', '["Rinse poha in a strainer and let it soften for 5 minutes.", "Heat oil, fry peanuts and set aside. Add mustard seeds, curry leaves and green chilli.", "Add onion (and diced potato if using) and cook until soft; add turmeric.", "Add poha, salt and sugar; toss gently and steam covered for 2 minutes.", "Finish with peanuts, lemon juice and coriander."]'::jsonb, true);
