INSERT INTO recipes (id, title, slug, description, cuisine, dietary_type, prep_time_minutes, cook_time_minutes, servings, difficulty, instructions, is_system_recipe) VALUES
  ('2015a985-4c43-5fcd-ad12-f6fc81eac64d', 'Rava Upma', 'rava-upma', 'Savoury semolina porridge with vegetables.', 'South Indian', 'vegetarian', 5, 15, 2, 'easy', '["Dry roast the semolina until aromatic and set aside.", "Heat ghee, add mustard seeds, urad dal, curry leaves, ginger and green chilli.", "Add onion and vegetables and saute for 3 minutes.", "Add 2.5 cups water and salt, bring to a boil and slowly add semolina while stirring.", "Cover and cook on low for 3 minutes."]'::jsonb, true);
