  ('06617b51-658e-57d1-9efb-0df5f7a322fc', 'Masala Omelette', 'masala-omelette', 'Fluffy omelette with onion, tomato and green chilli.', 'Indian', 'eggetarian', 5, 5, 1, 'easy', '["Beat the eggs with salt and a pinch of turmeric.", "Mix in finely chopped onion, tomato, green chilli and coriander.", "Heat oil in a pan, pour in the mixture and cook on medium heat until set; flip and cook 1 minute."]'::jsonb, true);
