INSERT INTO recipes (id, title, slug, description, cuisine, dietary_type, prep_time_minutes, cook_time_minutes, servings, difficulty, instructions, is_system_recipe) VALUES
  ('4f1828e6-c6e9-59c9-a4fc-b122f212d937', 'Besan Chilla', 'besan-chilla', 'Savoury gram flour pancakes with onion and tomato.', 'North Indian', 'vegan', 10, 15, 2, 'easy', '["Whisk gram flour with water, turmeric, carom seeds and salt into a pourable batter.", "Stir in chopped onion, tomato, green chilli and coriander.", "Spread a ladle of batter thinly on a hot greased tawa.", "Cook until golden on both sides, drizzling oil around the edges."]'::jsonb, true);
