INSERT INTO recipes (id, title, slug, description, cuisine, dietary_type, prep_time_minutes, cook_time_minutes, servings, difficulty, instructions, is_system_recipe) VALUES
  ('9dc6cdf9-8d0f-5745-af5d-17923379cb9f', 'Moong Dal Chilla', 'moong-dal-chilla', 'High-protein pancakes made from soaked moong dal.', 'North Indian', 'vegan', 240, 15, 2, 'easy', '["Soak moong dal for 3-4 hours and drain.", "Grind with ginger, green chilli and a little water to a smooth batter; add cumin and salt.", "Spread thinly on a hot greased tawa and top with onion and coriander.", "Cook until crisp, flip and cook briefly."]'::jsonb, true);
