INSERT INTO recipes (id, title, slug, description, cuisine, dietary_type, prep_time_minutes, cook_time_minutes, servings, difficulty, instructions, is_system_recipe) VALUES
  ('8047bdc0-0845-5ed9-8536-135d99cf974f', 'Masala Dosa', 'masala-dosa', 'Crisp dosa filled with spiced potato bhaji.', 'South Indian', 'vegetarian', 15, 25, 3, 'medium', '["Boil, peel and roughly mash the potatoes.", "Heat oil, add mustard seeds, curry leaves and green chilli, then sliced onion; cook until soft.", "Add turmeric, salt and the potatoes with a splash of water; mix well.", "Spread a ladle of batter thinly on a hot tawa, drizzle ghee and cook until crisp.", "Place the potato filling in the centre, fold and serve with chutney."]'::jsonb, true);
