  ('d079cb53-1e60-548b-a6f4-be5401b2f2d2', 'Idli', 'idli', 'Soft steamed rice-lentil cakes.', 'South Indian', 'vegetarian', 5, 15, 3, 'easy', '["Grease the idli moulds lightly.", "Stir salt into the batter and pour into the moulds.", "Steam for 10-12 minutes until a toothpick comes out clean.", "Rest 2 minutes, unmould and serve with sambar and chutney."]'::jsonb, true);
