  ('6f5e7cf6-cff1-5080-83b9-313099172633', 'Vegetable Uttapam', 'vegetable-uttapam', 'Thick dosa topped with onion, tomato and capsicum.', 'South Indian', 'vegetarian', 10, 15, 2, 'easy', '["Finely chop the vegetables and mix with coriander and green chilli.", "Pour a thick round of batter on a hot greased tawa.", "Press the vegetable mix on top, drizzle oil and cook covered for 2 minutes.", "Flip and cook for another minute."]'::jsonb, true);
