INSERT INTO recipes (id, title, slug, description, cuisine, dietary_type, prep_time_minutes, cook_time_minutes, servings, difficulty, instructions, is_system_recipe) VALUES
  ('a5da83a6-1a29-5ce9-9564-971e801b2828', 'Sabudana Khichdi', 'sabudana-khichdi', 'Soft sago pearls with peanuts and potato, a popular fasting dish.', 'Maharashtrian', 'vegetarian', 360, 15, 2, 'medium', '["Rinse and soak sabudana in just enough water to cover for 5-6 hours.", "Roast and coarsely crush the peanuts; mix into the sabudana with salt and sugar.", "Heat ghee, add cumin and green chilli, then boiled diced potato.", "Add the sabudana mix and cook on low heat, stirring, until the pearls turn translucent.", "Finish with lemon and coriander."]'::jsonb, true);
