INSERT INTO recipes (id, title, slug, description, cuisine, dietary_type, prep_time_minutes, cook_time_minutes, servings, difficulty, instructions, is_system_recipe) VALUES
  ('fc29c160-afe2-54e2-88de-c72476bc6015', 'Lemon Rice', 'lemon-rice', 'Tangy tempered rice - the best use for leftover cooked rice.', 'South Indian', 'vegan', 5, 10, 2, 'easy', '["Cook the rice and spread it out to cool (or use leftover rice).", "Heat oil, fry peanuts and chana dal, then add mustard seeds, curry leaves, green chilli and asafoetida.", "Add turmeric and immediately add the rice and salt.", "Turn off the heat, squeeze in lemon juice and mix gently."]'::jsonb, true);
