INSERT INTO recipes (id, title, slug, description, cuisine, dietary_type, prep_time_minutes, cook_time_minutes, servings, difficulty, instructions, is_system_recipe) VALUES
  ('919e6b97-d81f-5b1e-bb66-0c8dacba4d84', 'Curd Rice', 'curd-rice', 'Cooling yoghurt rice with a mustard-curry leaf tempering.', 'South Indian', 'vegetarian', 5, 5, 2, 'easy', '["Cook the rice soft and mash it slightly while warm; let it cool.", "Mix in curd, milk and salt.", "Temper oil with mustard seeds, curry leaves, ginger and green chilli and pour over.", "Add grated cucumber if using and serve chilled or at room temperature."]'::jsonb, true);
