  ('45a72b1e-8127-57f6-b6d6-1400ad2a8c63', 'Coconut Chutney', 'coconut-chutney', 'Fresh coconut chutney for dosa and idli.', 'South Indian', 'vegan', 10, 2, 3, 'easy', '["Grind coconut, peanuts, green chilli, ginger and salt with a little water until smooth.", "Temper oil with mustard seeds and curry leaves and pour over the chutney."]'::jsonb, true);
