INSERT INTO recipes (id, title, slug, description, cuisine, dietary_type, prep_time_minutes, cook_time_minutes, servings, difficulty, instructions, is_system_recipe) VALUES
  ('097a7fd6-49f1-5b6e-9ad0-9ab136a3a442', 'Avial', 'avial', 'Mixed vegetables in a coconut-curd sauce finished with coconut oil.', 'Kerala', 'vegetarian', 20, 20, 3, 'medium', '["Cut vegetables into long batons and cook with turmeric, salt and a little water until just tender.", "Grind coconut, cumin and green chilli to a coarse paste.", "Add the paste to the vegetables and cook for 3 minutes.", "Turn off the heat, stir in whisked curd, and finish with coconut oil and curry leaves."]'::jsonb, true);
