  ('1cc383c2-05da-5e77-9f47-02ffc04db45d', 'Beans Poriyal', 'beans-poriyal', 'Stir-fried beans with coconut.', 'South Indian', 'vegan', 10, 10, 2, 'easy', '["Finely chop the beans.", "Heat oil, add mustard seeds, urad dal, curry leaves and green chilli.", "Add beans and salt with a splash of water; cover and cook for 6-8 minutes.", "Add grated coconut and toss for a minute."]'::jsonb, true);
