  ('e9ef1705-2847-510b-96a5-ff2c38fac9d7', 'Tomato Rice', 'tomato-rice', 'Spiced tomato rice, great in a lunch box.', 'South Indian', 'vegan', 10, 20, 2, 'easy', '["Cook rice and let it cool.", "Heat oil, add mustard seeds and curry leaves, then onion and ginger garlic paste.", "Add chopped tomato and spices; cook until thick and pulpy.", "Fold in the rice and salt gently."]'::jsonb, true);
