INSERT INTO recipes (id, title, slug, description, cuisine, dietary_type, prep_time_minutes, cook_time_minutes, servings, difficulty, instructions, is_system_recipe) VALUES
  ('3d627bf4-5cd0-5cfe-8a13-032e1e8594db', 'Pav Bhaji', 'pav-bhaji', 'Buttery mashed vegetable curry served with toasted pav.', 'Street Food', 'vegetarian', 15, 30, 3, 'medium', '["Boil potatoes, peas and cauliflower until soft and mash.", "Melt butter, saute onion and ginger garlic paste, then capsicum and tomato until mushy.", "Add pav bhaji masala, chilli powder and salt, then the mashed vegetables and a cup of water.", "Simmer and mash well for 10 minutes, finishing with more butter and coriander.", "Toast the pav in butter and serve with lemon and chopped onion."]'::jsonb, true);
