INSERT INTO recipes (id, title, slug, description, cuisine, dietary_type, prep_time_minutes, cook_time_minutes, servings, difficulty, instructions, is_system_recipe) VALUES
  ('e44187ac-0ee6-598c-9c3c-8febe1b3377c', 'Vada Pav', 'vada-pav', 'Mumbai''s spiced potato fritter in a pav.', 'Maharashtrian', 'vegan', 20, 20, 3, 'medium', '["Boil and mash the potatoes.", "Temper mustard seeds, curry leaves, green chilli and ginger garlic paste; add turmeric and the potatoes; shape into balls.", "Make a thick batter of gram flour, salt, turmeric and water.", "Dip the potato balls in the batter and deep fry until golden.", "Serve in a slit pav with chutney."]'::jsonb, true);
