  ('4ae2071a-5942-5964-b870-411aee1701d2', 'Masala Maggi', 'masala-maggi', 'Desi instant noodles with vegetables.', 'Indo-Chinese', 'vegetarian', 5, 10, 1, 'easy', '["Heat oil and saute onion, green chilli and vegetables for 2 minutes.", "Add tomato and cook until soft.", "Add 1.5 cups water and the tastemaker; bring to a boil.", "Add the noodles and cook for 2 minutes until the water is mostly absorbed."]'::jsonb, true);
