INSERT INTO recipes (id, title, slug, description, cuisine, dietary_type, prep_time_minutes, cook_time_minutes, servings, difficulty, instructions, is_system_recipe) VALUES
  ('c3e766d6-0d9f-5479-867a-baa0191910b1', 'Veg Hakka Noodles', 'veg-hakka-noodles', 'Street-style stir-fried noodles with crunchy vegetables.', 'Indo-Chinese', 'vegan', 15, 10, 2, 'easy', '["Boil the noodles (without tastemaker) until al dente, drain and toss in a little oil.", "Heat oil on high, add chopped garlic and stir-fry the shredded vegetables for 2 minutes.", "Add noodles, soy sauce, vinegar, salt and pepper; toss on high heat.", "Finish with spring onion greens."]'::jsonb, true);
