INSERT INTO recipes (id, title, slug, description, cuisine, dietary_type, prep_time_minutes, cook_time_minutes, servings, difficulty, instructions, is_system_recipe) VALUES
  ('36d62e42-b4dc-5c7d-bf8b-4050bd20385b', 'Veg Fried Rice', 'veg-fried-rice', 'Wok-tossed rice with vegetables - perfect for leftover rice.', 'Indo-Chinese', 'vegan', 10, 10, 2, 'easy', '["Use cold cooked rice (day-old rice works best).", "Heat oil on high, add garlic and the finely chopped vegetables; stir-fry for 2-3 minutes.", "Add rice, soy sauce, salt and pepper and toss well on high heat.", "Garnish with spring onions."]'::jsonb, true);
