  ('1279eff8-fb7b-55b5-a08a-6605121e165a', 'Chilli Paneer', 'chilli-paneer', 'Crisp paneer tossed with peppers in a spicy soy-chilli sauce.', 'Indo-Chinese', 'vegetarian', 15, 15, 2, 'medium', '["Toss paneer cubes in cornflour or maida with salt and shallow fry until golden.", "Stir-fry garlic, green chilli, onion petals and capsicum on high heat for 2 minutes.", "Add soy sauce, chilli sauce and ketchup, then a splash of water.", "Toss in the paneer and garnish with spring onions."]'::jsonb, true);
