  ('2d430d7d-52b1-563e-b06a-3c497b9625d6', 'Masala Pasta', 'masala-pasta', 'Indian-style tomato pasta with vegetables.', 'Indo-Italian', 'vegetarian', 10, 20, 2, 'easy', '["Boil the pasta in salted water until al dente and drain.", "Saute garlic and onion in oil, then capsicum and corn.", "Add chopped tomato and spices and cook into a thick sauce.", "Toss the pasta in the sauce and top with grated cheese."]'::jsonb, true);
