  ('0101b7d5-d3b2-54e9-ae96-f51031904b20', 'Aloo Tikki', 'aloo-tikki', 'Crispy spiced potato patties.', 'Street Food', 'vegetarian', 15, 15, 3, 'easy', '["Boil, peel and mash the potatoes.", "Mix in peas, ginger, green chilli, spices, coriander and a slice of crumbled bread to bind.", "Shape into patties.", "Shallow fry on a tawa until crisp on both sides. Serve with chutney."]'::jsonb, true);
