INSERT INTO recipes (id, title, slug, description, cuisine, dietary_type, prep_time_minutes, cook_time_minutes, servings, difficulty, instructions, is_system_recipe) VALUES
  ('5d49d330-0fda-5f4d-8adb-794319236b00', 'Paneer Tikka', 'paneer-tikka', 'Marinated paneer and vegetables grilled on a pan or in the oven.', 'North Indian', 'vegetarian', 30, 15, 2, 'medium', '["Whisk curd with ginger garlic paste, chilli powder, garam masala, lemon and salt.", "Coat paneer, capsicum and onion cubes and marinate for 30 minutes.", "Thread onto skewers or arrange in a pan.", "Grill or pan-roast with a little oil until charred at the edges. Sprinkle chaat masala."]'::jsonb, true);
