INSERT INTO recipes (id, title, slug, description, cuisine, dietary_type, prep_time_minutes, cook_time_minutes, servings, difficulty, instructions, is_system_recipe) VALUES
  ('548b6580-9ff4-5200-8813-00cef0a65c22', 'Chicken Curry', 'chicken-curry', 'Homestyle chicken in an onion-tomato gravy.', 'North Indian', 'non-vegetarian', 15, 40, 3, 'medium', '["Marinate chicken with curd, turmeric, chilli powder and salt for 20 minutes.", "Heat oil, add cumin and fry the onion until deep brown; add ginger garlic paste.", "Add tomato and coriander powder and cook until oil separates.", "Add the chicken and sear for 5 minutes, then add 1 cup water and simmer covered for 25 minutes.", "Finish with garam masala and coriander."]'::jsonb, true);
