INSERT INTO recipes (id, title, slug, description, cuisine, dietary_type, prep_time_minutes, cook_time_minutes, servings, difficulty, instructions, is_system_recipe) VALUES
  ('8969b3bd-05a5-54b9-9cfc-a3de74df4db8', 'Butter Chicken', 'butter-chicken', 'Tandoori-style chicken in a creamy tomato-butter sauce.', 'North Indian', 'non-vegetarian', 30, 35, 3, 'medium', '["Marinate chicken in curd, ginger garlic paste, chilli powder, garam masala and salt for 30 minutes.", "Sear the chicken in a hot pan with oil until charred; set aside.", "Simmer tomatoes and cashews, blend smooth and cook in butter for 8 minutes.", "Add chicken, cream, sugar and crushed kasuri methi; simmer for 10 minutes."]'::jsonb, true);
