INSERT INTO recipes (id, title, slug, description, cuisine, dietary_type, prep_time_minutes, cook_time_minutes, servings, difficulty, instructions, is_system_recipe) VALUES
  ('8ec1dcd2-3d58-56dd-a5e2-5eb432cce432', 'Egg Curry', 'egg-curry', 'Boiled eggs in a spiced onion-tomato gravy.', 'Indian', 'eggetarian', 10, 25, 2, 'easy', '["Hard boil the eggs for 10 minutes, peel and make shallow slits.", "Fry the eggs lightly in oil with turmeric and chilli; set aside.", "In the same oil add cumin, onion and ginger garlic paste; fry until golden.", "Add tomato and spices, cook until thick, then add 1 cup water.", "Add eggs, simmer for 5 minutes and garnish."]'::jsonb, true);
