INSERT INTO recipes (id, title, slug, description, cuisine, dietary_type, prep_time_minutes, cook_time_minutes, servings, difficulty, instructions, is_system_recipe) VALUES
  ('79267e76-c57c-5bda-a7fa-0526124aa7dc', 'Chicken Biryani', 'chicken-biryani', 'Layered basmati rice and spiced chicken cooked on dum.', 'Hyderabadi', 'non-vegetarian', 45, 45, 4, 'hard', '["Marinate chicken with curd, ginger garlic paste, biryani masala, chilli, turmeric and salt for 30 minutes.", "Thinly slice and fry the onions until deep brown.", "Par-boil soaked rice in salted water until 70% cooked; drain.", "Cook the chicken with half the fried onions until nearly done.", "Layer rice over the chicken with mint, coriander, remaining onions, saffron milk and ghee; seal and cook on low for 20 minutes."]'::jsonb, true);
