  ('f89e3c1c-da64-5907-a611-55693827900d', 'Keema Matar', 'keema-matar', 'Spiced minced meat cooked with green peas.', 'North Indian', 'non-vegetarian', 10, 35, 3, 'medium', '["Heat oil, add cumin and onion; fry until golden, then add ginger garlic paste.", "Add the keema and cook on high, breaking up lumps, until it changes colour.", "Add tomato and spices and cook for 10 minutes.", "Add peas and half a cup of water; cover and cook for 15 minutes. Finish with garam masala."]'::jsonb, true);
