  ('72614fa0-9ea5-5421-84d4-2f8ea97a4509', 'Goan Fish Curry', 'goan-fish-curry', 'Tangy coconut fish curry.', 'Goan', 'non-vegetarian', 15, 25, 3, 'medium', '["Rub fish with turmeric and salt and keep aside.", "Saute onion and ginger garlic paste, then tomato and the powdered spices.", "Add tamarind extract and coconut milk; simmer for 5 minutes.", "Slide in the fish and simmer gently for 8-10 minutes without stirring vigorously."]'::jsonb, true);
