  ('2412564b-22bc-57fa-a51f-be02bc5fbc45', 'Prawn Masala', 'prawn-masala', 'Prawns cooked in a thick, spicy onion-tomato masala.', 'Coastal', 'non-vegetarian', 15, 20, 2, 'medium', '["Clean and devein the prawns; marinate with turmeric and salt.", "Fry onion until golden, add ginger garlic paste and curry leaves.", "Add tomato and spices and cook until oil separates.", "Add prawns and cook for 5-6 minutes until just opaque."]'::jsonb, true);
