  ('29646fb2-88a3-5e10-8e85-eb19540c48cf', 'Mutton Curry', 'mutton-curry', 'Slow-cooked mutton in a rich onion gravy.', 'North Indian', 'non-vegetarian', 20, 60, 4, 'hard', '["Marinate mutton with curd, ginger garlic paste, turmeric and salt for 1 hour.", "Fry onions with bay leaf until deep brown.", "Add mutton and sear on high for 10 minutes.", "Add tomato and spices and cook until oil separates.", "Pressure cook with 1.5 cups water for 5-6 whistles; finish with garam masala."]'::jsonb, true);
