INSERT INTO recipes (id, title, slug, description, cuisine, dietary_type, prep_time_minutes, cook_time_minutes, servings, difficulty, instructions, is_system_recipe) VALUES
  ('dcb1c2cb-a2e3-52a3-a3d9-f17e10aa2521', 'Chilli Chicken', 'chilli-chicken', 'Crisp chicken tossed with peppers in a soy-chilli sauce.', 'Indo-Chinese', 'non-vegetarian', 20, 20, 2, 'medium', '["Coat chicken with egg, flour, salt and a dash of soy sauce.", "Deep or shallow fry until crisp; drain.", "Stir-fry garlic, green chilli, onion and capsicum on high heat.", "Add sauces and a splash of water, then toss the chicken to coat."]'::jsonb, true);
