  ('da4df9b7-5bfc-5aa1-a7b4-cd62110e9c33', 'Chicken Fried Rice', 'chicken-fried-rice', 'Fried rice with chicken and egg.', 'Indo-Chinese', 'non-vegetarian', 15, 15, 2, 'easy', '["Use cold cooked rice.", "Stir-fry small chicken pieces with garlic until cooked; push aside and scramble the eggs.", "Add vegetables, then rice, soy sauce, salt and pepper; toss on high heat.", "Garnish with spring onion."]'::jsonb, true);
