INSERT INTO recipes (id, title, slug, description, cuisine, dietary_type, prep_time_minutes, cook_time_minutes, servings, difficulty, instructions, is_system_recipe) VALUES
  ('845dbe6a-0d82-5567-8204-357841940366', 'Suji Halwa', 'suji-halwa', 'Semolina pudding with ghee, sugar and cardamom.', 'North Indian', 'vegetarian', 5, 15, 3, 'easy', '["Heat ghee and roast the semolina on low heat until golden and fragrant.", "Meanwhile boil 1.5 cups water with sugar.", "Carefully pour the hot syrup into the semolina while stirring.", "Cook until it thickens and leaves the sides; add cardamom and nuts."]'::jsonb, true);
