INSERT INTO recipes (id, title, slug, description, cuisine, dietary_type, prep_time_minutes, cook_time_minutes, servings, difficulty, instructions, is_system_recipe) VALUES
  ('5f1e83a5-dd82-5bc0-9e08-af7a1eb97dab', 'Rice Kheer', 'rice-kheer', 'Slow-cooked creamy rice pudding.', 'North Indian', 'vegetarian', 10, 45, 4, 'easy', '["Soak the rice for 20 minutes.", "Bring milk to a boil in a heavy pan and add the drained rice.", "Simmer on low heat, stirring often, for 35-40 minutes until the rice is soft and the milk thickens.", "Stir in sugar, cardamom, saffron and nuts; cook for 5 more minutes."]'::jsonb, true);
