  ('8c42dfe1-3f88-5642-93d3-10db23c04e84', 'Gajar Halwa', 'gajar-halwa', 'Winter favourite - grated carrots slow-cooked in milk.', 'North Indian', 'vegetarian', 15, 50, 4, 'medium', '["Grate the carrots.", "Cook carrots in milk on medium heat, stirring, until the milk is almost absorbed (30-35 minutes).", "Add sugar and ghee and cook until glossy and thick.", "Stir in khoya, cardamom and nuts."]'::jsonb, true);
