  ('10899d21-5339-5bac-8b7c-79ed56616d51', 'Seviyan Kheer', 'seviyan-kheer', 'Quick vermicelli milk pudding.', 'North Indian', 'vegetarian', 5, 20, 3, 'easy', '["Roast the vermicelli in ghee until golden.", "Add milk and bring to a boil, then simmer for 10 minutes.", "Add sugar and cardamom and cook until slightly thick.", "Garnish with almonds."]'::jsonb, true);
